PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS reading_months (id INTEGER PRIMARY KEY, title TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, required_count INTEGER NOT NULL CHECK(required_count>=0));
CREATE TABLE IF NOT EXISTS reading_books (id INTEGER PRIMARY KEY, month_id INTEGER REFERENCES reading_months(id) ON DELETE RESTRICT, slot INTEGER NOT NULL CHECK(slot>=1), title TEXT NOT NULL, author TEXT NOT NULL, is_short INTEGER NOT NULL DEFAULT 0 CHECK(is_short IN(0,1)), is_bonus INTEGER NOT NULL DEFAULT 0 CHECK(is_bonus IN(0,1)), is_reread INTEGER NOT NULL DEFAULT 0 CHECK(is_reread IN(0,1)), bespoke_assignment TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS reading_book_state (book_id INTEGER PRIMARY KEY REFERENCES reading_books(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'NOT_STARTED' CHECK(status IN('NOT_STARTED','READING','REPORT_DUE','COMPLETE')), started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS reading_reports (book_id INTEGER PRIMARY KEY REFERENCES reading_books(id) ON DELETE CASCADE, recall TEXT NOT NULL DEFAULT '', core_idea TEXT NOT NULL DEFAULT '', bespoke_response TEXT NOT NULL DEFAULT '', evidence_notes TEXT NOT NULL DEFAULT '', push_back TEXT NOT NULL DEFAULT '', connection TEXT NOT NULL DEFAULT '', keep_one TEXT NOT NULL DEFAULT '', updated_at TEXT);
CREATE TRIGGER IF NOT EXISTS reading_complete_requires_report BEFORE UPDATE OF status ON reading_book_state WHEN NEW.status='COMPLETE' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM reading_reports r WHERE r.book_id=NEW.book_id AND length(trim(r.recall))>0 AND length(trim(r.core_idea))>0 AND length(trim(r.bespoke_response))>0 AND length(trim(r.evidence_notes))>0 AND length(trim(r.push_back))>0 AND length(trim(r.connection))>0 AND length(trim(r.keep_one))>0) THEN RAISE(ABORT,'Reading report is incomplete.') END; END;
CREATE TABLE IF NOT EXISTS practice_stages (id INTEGER PRIMARY KEY, sort_order INTEGER NOT NULL UNIQUE CHECK(sort_order>=0), title TEXT NOT NULL, goal TEXT NOT NULL, unlock_after_stage_id INTEGER REFERENCES practice_stages(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS practice_lessons (id INTEGER PRIMARY KEY, stage_id INTEGER NOT NULL REFERENCES practice_stages(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL CHECK(sort_order>=1), title TEXT NOT NULL, concept TEXT NOT NULL, practice_assignment TEXT NOT NULL, review_prompts TEXT NOT NULL, UNIQUE(stage_id,sort_order));
CREATE TABLE IF NOT EXISTS practice_resources (id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL REFERENCES practice_lessons(id) ON DELETE CASCADE, label TEXT NOT NULL, url TEXT NOT NULL, resource_type TEXT NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS practice_lesson_state (lesson_id INTEGER PRIMARY KEY REFERENCES practice_lessons(id) ON DELETE CASCADE, learned INTEGER NOT NULL DEFAULT 0 CHECK(learned IN(0,1)), practiced INTEGER NOT NULL DEFAULT 0 CHECK(practiced IN(0,1)), reviewed INTEGER NOT NULL DEFAULT 0 CHECK(reviewed IN(0,1)), selected_explained INTEGER NOT NULL DEFAULT 0 CHECK(selected_explained IN(0,1)), notes TEXT NOT NULL DEFAULT '', completed_at TEXT);
CREATE TABLE IF NOT EXISTS practice_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, lesson_id INTEGER REFERENCES practice_lessons(id) ON DELETE SET NULL, title TEXT NOT NULL CHECK(length(trim(title))>0), practice_date TEXT NOT NULL, goal TEXT NOT NULL DEFAULT '', quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), representative_file TEXT, best_notes TEXT NOT NULL DEFAULT '', worst_notes TEXT NOT NULL DEFAULT '', reflection TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS practice_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS practice_preferences (category_id INTEGER PRIMARY KEY REFERENCES practice_categories(id) ON DELETE CASCADE, rating TEXT, note TEXT NOT NULL DEFAULT '', updated_at TEXT);
CREATE TABLE IF NOT EXISTS practice_challenges (id INTEGER PRIMARY KEY, minimum_stage_order INTEGER NOT NULL CHECK(minimum_stage_order>=0), title TEXT NOT NULL, prompt TEXT NOT NULL);
